+        fatal("cannot read $label: $source");
+    print {$fh} $content ||
+        fatal("cannot read $label: $source");
+    close $fh || fatal("cannot read $label: $source");
+}
+
+sub file_size {
+    my ($path) = @_;
+    my @metadata = stat($path);
