+    my ($path, $pattern) = @_;
+
+    open my $fh, '<:raw', $path or return 0;
+    while (my $line = <$fh>) {
+        if ($line =~ $pattern) {
+            close $fh;
+            return 1;
+        }
+    }
+    close $fh;
+    return 0;
+}
