+        my $read = sysread($fh, $buffer, 65_536);
+        defined($read) || last;
+        last if $read == 0;
+        if (index($buffer, $needle) >= 0) {
+            close $fh;
+            return 1;
+        }
+    }
+    close $fh;
+    return 0;
