+sub verify_source_profile_modes {
+    my ($entries, $profile_dir) = @_;
+
+    for my $entry (@$entries) {
+        profile_mode_matches(
+            $entry->{mode},
+            $entry->{name},
+            $entry->{path},
+            $profile_dir,
+        ) || fatal(
+            'AppArmor profile source mode mismatch: '
+            . "$entry->{name} expected=$entry->{mode}"
+        );
+    }
+}
