+package AppArmor::ManagedModes::Workspace;
+
+use strict;
+use warnings;
+
+use File::Copy qw(copy);
+use File::Path qw(remove_tree);
+use File::Temp qw(tempdir tempfile);
+
+use AppArmor::ManagedModes::CLI qw(fatal);
+
+sub new {
+    my ($class) = @_;
+    my $tmp_root = defined($ENV{TMPDIR}) && $ENV{TMPDIR} ne ''
+        ? $ENV{TMPDIR}
+        : '/tmp';
+
+    return bless {
+        directories => {},
+        files       => {},
+        tmp_root    => $tmp_root,
+    }, $class;
+}
+
+sub tempfile {
+    my ($self, $label) = @_;
+    my ($fh, $path) = tempfile(
+        "$label.XXXXXX",
+        DIR    => $self->{tmp_root},
+        UNLINK => 0,
+    );
+    binmode $fh, ':raw' ||
+        fatal("cannot create $label snapshot");
+    $self->{files}{$path} = 1;
+    return ($fh, $path);
+}
+
+sub tempdir {
+    my ($self, $label) = @_;
+    my $path = tempdir(
+        "$label.XXXXXX",
+        DIR     => $self->{tmp_root},
+        CLEANUP => 0,
+    );
+    $self->{directories}{$path} = 1;
+    return $path;
+}
+
+sub copy_file {
+    my ($self, $source, $target, $message) = @_;
+
+    copy($source, $target) || fatal($message);
+    chmod 0644, $target || fatal($message);
+}
+
+sub truncate_file {
+    my ($self, $path) = @_;
+
+    open my $fh, '>:raw', $path ||
+        fatal("cannot create AppArmor profile name snapshot: $path");
+    close $fh ||
+        fatal("cannot create AppArmor profile name snapshot: $path");
+}
+
+sub track_file {
+    my ($self, $path) = @_;
+    $self->{files}{$path} = 1;
+}
+
+sub forget_file {
+    my ($self, $path) = @_;
+    delete $self->{files}{$path};
+}
+
+sub remove_file {
+    my ($self, $path) = @_;
+    unlink $path if -e $path || -l $path;
+    delete $self->{files}{$path};
+}
+
+sub remove_dir {
+    my ($self, $path) = @_;
+    remove_tree($path, { safe => 1 }) if -d $path && !-l $path;
+    delete $self->{directories}{$path};
+}
+
+sub cleanup {
+    my ($self) = @_;
+
+    for my $path (sort { length($b) <=> length($a) } keys %{$self->{directories}}) {
+        remove_tree($path, { safe => 1 }) if -d $path && !-l $path;
+    }
+    for my $path (keys %{$self->{files}}) {
+        unlink $path if -e $path || -l $path;
+    }
+    $self->{directories} = {};
+    $self->{files} = {};
+}
+
+1;
