#!/usr/bin/perl

use strict;
use warnings;

use FindBin qw($RealBin);
use lib "$RealBin/../libexec/apparmor-managed-modes",
    '/usr/local/libexec/apparmor-managed-modes';

use AppArmor::ManagedModes::CLI qw(fatal info parse_args);
use AppArmor::ManagedModes::Config qw(load_config);
use AppArmor::ManagedModes::Tool;
use AppArmor::ManagedModes::Transition qw(apply_profile_mode);
use AppArmor::ManagedModes::TrustedPath qw(
    validate_absolute_path
    validate_real_directory
);
use AppArmor::ManagedModes::Verify qw(
    verify_loaded_profile_modes
    verify_source_profile_modes
);
use AppArmor::ManagedModes::Workspace;

my $options = parse_args(@ARGV);

validate_absolute_path('configuration path', $options->{config_path});
validate_absolute_path('profile directory', $options->{profile_dir});
validate_absolute_path('tool directory', $options->{tool_dir});
validate_absolute_path('loaded profiles path', $options->{loaded_profiles_path});
validate_real_directory('profile directory', $options->{profile_dir});

umask 0077;

my $workspace = AppArmor::ManagedModes::Workspace->new();
END {
    $workspace->cleanup() if defined $workspace;
}

my $entries = load_config($options);
my $tools = AppArmor::ManagedModes::Tool->new();

if ($options->{check_only}) {
    verify_source_profile_modes($entries, $options->{profile_dir});
}
else {
    for my $entry (@$entries) {
        next if $entry->{mode} ne 'disable';
        apply_profile_mode($entry, $options, $workspace, $tools);
    }
    for my $entry (@$entries) {
        next if $entry->{mode} eq 'disable';
        apply_profile_mode($entry, $options, $workspace, $tools);
    }
}

if ($options->{check_loaded} ||
    (!$options->{check_only} && $options->{reload_profiles})) {
    verify_loaded_profile_modes($entries, $options, $workspace, $tools);
}

info('mode policy verified');
exit 0;

package AppArmor::ManagedModes::CLI;

use strict;
use warnings;

use Exporter qw(import);

our @EXPORT_OK = qw(fatal info parse_args usage warn);

sub fatal {
    my ($message) = @_;
    print STDERR "fatal: $message\n";
    exit 1;
}

sub info {
    my ($message) = @_;
    print "apparmor-managed-modes: $message\n";
}

sub warn {
    my ($message) = @_;
    print STDERR "apparmor-managed-modes: warning: $message\n";
}

sub usage {
    print <<'USAGE';
Usage: apparmor-managed-modes [--check] [--check-loaded] [--no-reload]
                               [--config PATH] [--profile-dir PATH]
                               [--tool-dir PATH] [--loaded-profiles PATH]
USAGE
}

sub parse_args {
    my @argv = @_;
    my $options = {
        config_path          => '/etc/apparmor/managed-modes.conf',
        profile_dir          => '/etc/apparmor.d',
        tool_dir             => '/usr/sbin',
        reload_profiles      => 1,
        check_only           => 0,
        check_loaded         => 0,
        loaded_profiles_path => '/sys/kernel/security/apparmor/profiles',
    };

    while (@argv) {
        my $argument = shift @argv;

        if ($argument eq '--check') {
            $options->{check_only} = 1;
        }
        elsif ($argument eq '--check-loaded') {
            $options->{check_only} = 1;
            $options->{check_loaded} = 1;
        }
        elsif ($argument eq '--no-reload') {
            $options->{reload_profiles} = 0;
        }
        elsif ($argument eq '--config') {
            @argv or fatal('--config requires a path');
            $options->{config_path} = shift @argv;
        }
        elsif ($argument eq '--profile-dir') {
            @argv or fatal('--profile-dir requires a path');
            $options->{profile_dir} = shift @argv;
        }
        elsif ($argument eq '--tool-dir') {
            @argv or fatal('--tool-dir requires a path');
            $options->{tool_dir} = shift @argv;
        }
        elsif ($argument eq '--loaded-profiles') {
            @argv or fatal('--loaded-profiles requires a path');
            $options->{loaded_profiles_path} = shift @argv;
        }
        elsif ($argument eq '-h' || $argument eq '--help') {
            usage();
            exit 0;
        }
        else {
            fatal("unsupported argument: $argument");
        }
    }

    return $options;
}

1;

package AppArmor::ManagedModes::TrustedPath;

use strict;
use warnings;

use Exporter qw(import);

use AppArmor::ManagedModes::CLI qw(fatal);

our @EXPORT_OK = qw(
    bounded_capture
    file_size
    read_bounded_file
    validate_absolute_path
    validate_real_directory
    validate_root_owned_file
);

sub validate_absolute_path {
    my ($label, $value) = @_;
    my $shown_value = defined($value) && $value ne '' ? $value : 'unset';

    defined($value) && $value =~ m{\A/} ||
        fatal("$label must be an absolute path: $shown_value");
    $value ne '/' &&
        index($value, '..') == -1 &&
        index($value, '//') == -1 &&
        $value !~ /[^A-Za-z0-9._\/\@%:+,\-]/ ||
        fatal("$label contains unsupported path syntax: $value");
}

sub validate_real_directory {
    my ($label, $path) = @_;

    -d $path && !-l $path ||
        fatal("$label must be a real directory: $path");
}

sub validate_root_owned_file {
    my ($label, $path, $max_bytes) = @_;

    -f $path && !-l $path ||
        fatal("$label must be a regular non-symlink file: $path");
    my @metadata = lstat($path);
    @metadata || fatal("cannot inspect file metadata: $path");
    ($metadata[2] & 0170000) == 0100000 ||
        fatal("$label must be a regular non-symlink file: $path");
    $metadata[4] == 0 ||
        fatal("$label must be owned by root: $path");
    !($metadata[2] & 0022) ||
        fatal("$label must not be group- or world-writable: $path");
    $metadata[7] <= $max_bytes ||
        fatal("$label exceeds ${max_bytes} bytes: $path");
}

sub read_bounded_file {
    my ($label, $path, $max_bytes) = @_;

    -l $path && fatal("$label must not be a symlink: $path");
    open my $fh, '<:raw', $path ||
        fatal("cannot read $label: $path");

    my $content = '';
    my $remaining = $max_bytes + 1;
    while ($remaining > 0) {
        my $buffer = '';
        my $read = sysread(
            $fh,
            $buffer,
            $remaining > 65_536 ? 65_536 : $remaining,
        );
        defined($read) || fatal("cannot read $label: $path");
        last if $read == 0;
        $content .= $buffer;
        $remaining -= $read;
    }
    close $fh || fatal("cannot read $label: $path");

    length($content) <= $max_bytes ||
        fatal("$label exceeds ${max_bytes} bytes: $path");
    return $content;
}

sub bounded_capture {
    my ($label, $source, $target, $max_bytes) = @_;
    my $content = read_bounded_file($label, $source, $max_bytes);

    open my $fh, '>:raw', $target ||
        fatal("cannot read $label: $source");
    print {$fh} $content ||
        fatal("cannot read $label: $source");
    close $fh || fatal("cannot read $label: $source");
}

sub file_size {
    my ($path) = @_;
    my @metadata = stat($path);
    @metadata || fatal("cannot inspect file metadata: $path");
    return $metadata[7];
}

1;

package AppArmor::ManagedModes::Config;

use strict;
use warnings;

use Exporter qw(import);

use AppArmor::ManagedModes::CLI qw(fatal info warn);
use AppArmor::ManagedModes::TrustedPath qw(
    read_bounded_file
    validate_absolute_path
    validate_root_owned_file
);

our @EXPORT_OK = qw(limits load_config);

sub limits {
    return {
        max_config_bytes          => 65_536,
        max_profile_bytes         => 1_048_576,
        max_line_bytes            => 1_024,
        max_loaded_profiles_bytes => 8_388_608,
        max_profile_names_bytes   => 65_536,
    };
}

sub load_config {
    my ($options) = @_;
    my $limits = limits();

    validate_root_owned_file(
        'mode configuration',
        $options->{config_path},
        $limits->{max_config_bytes},
    );

    my $content = read_bounded_file(
        'mode configuration',
        $options->{config_path},
        $limits->{max_config_bytes},
    );
    my @lines = length($content) ? split(/\n/, $content, -1) : ();
    pop @lines if @lines && $content =~ /\n\z/;

    my @entries;
    my %seen_profiles;
    my $line_number = 0;

    for my $line (@lines) {
        ++$line_number;
        length($line) <= $limits->{max_line_bytes} ||
            fatal(
                "configuration line $line_number exceeds "
                . "$limits->{max_line_bytes} bytes"
            );
        next if $line eq '' || $line =~ /\A#/;

        $line =~ /\A[A-Za-z0-9._\/\@%:+,\-]+(?: +[A-Za-z0-9._\/\@%:+,\-]+){3}\z/ ||
            fatal(
                "configuration line $line_number contains unsupported "
                . 'characters or spacing'
            );

        my @fields = split(/ +/, $line, -1);
        @fields == 4 ||
            fatal(
                "configuration line $line_number must contain exactly four fields"
            );

        my ($mode, $presence, $profile_name, $executable_probe) = @fields;
        $mode =~ /\A(?:enforce|complain|disable)\z/ ||
            fatal(
                "configuration line $line_number has an invalid mode: $mode"
            );
        $presence =~ /\A(?:required|optional|if-executable)\z/ ||
            fatal(
                "configuration line $line_number has an invalid presence policy: "
                . $presence
            );
        $profile_name =~ /\A[A-Za-z0-9._+\-]+\z/ ||
            fatal(
                "configuration line $line_number has an invalid profile file: "
                . $profile_name
            );
        !$seen_profiles{$profile_name}++ ||
            fatal(
                "configuration line $line_number repeats profile file: "
                . $profile_name
            );

        if ($presence eq 'if-executable') {
            validate_absolute_path(
                'configuration executable probe',
                $executable_probe,
            );
        }
        else {
            $executable_probe eq '-' ||
                fatal(
                    "configuration line $line_number must use '-' "
                    . 'as its executable probe'
                );
        }

        if ($presence eq 'if-executable' && !-x $executable_probe) {
            info(
                "skipping profile $profile_name; executable is absent: "
                . $executable_probe
            );
            next;
        }

        my $profile_path = "$options->{profile_dir}/$profile_name";
        if (!-e $profile_path) {
            if ($presence eq 'required') {
                fatal("required AppArmor profile is missing: $profile_name");
            }
            if ($presence eq 'if-executable') {
                warn(
                    'installed executable has no package AppArmor profile; '
                    . "skipping mode management: $executable_probe -> "
                    . $profile_name
                );
            }
            else {
                info("skipping absent optional profile $profile_name");
            }
            next;
        }

        validate_root_owned_file(
            'AppArmor profile',
            $profile_path,
            $limits->{max_profile_bytes},
        );
        push @entries, {
            mode => $mode,
            name => $profile_name,
            path => $profile_path,
        };
    }

    return \@entries;
}

1;

package AppArmor::ManagedModes::Verify;

use strict;
use warnings;

use Exporter qw(import);

use AppArmor::ManagedModes::CLI qw(fatal info);
use AppArmor::ManagedModes::Config qw(limits);
use AppArmor::ManagedModes::LoadedState qw(
    contains_exact_line
    contains_label_prefix
    read_snapshot
);
use AppArmor::ManagedModes::Transition qw(profile_mode_matches);
use AppArmor::ManagedModes::TrustedPath qw(
    bounded_capture
    file_size
);

our @EXPORT_OK = qw(
    verify_loaded_profile_modes
    verify_source_profile_modes
);

sub verify_source_profile_modes {
    my ($entries, $profile_dir) = @_;

    for my $entry (@$entries) {
        profile_mode_matches(
            $entry->{mode},
            $entry->{name},
            $entry->{path},
            $profile_dir,
        ) || fatal(
            'AppArmor profile source mode mismatch: '
            . "$entry->{name} expected=$entry->{mode}"
        );
    }
}

sub verify_loaded_profile_modes {
    my ($entries, $options, $workspace, $tools) = @_;
    my $limits = limits();
    my $parser_path = "$options->{tool_dir}/apparor_parser";
    $parser_path = "$options->{tool_dir}/apparmor_parser";
    $tools->require_executable('required AppArmor parser', $parser_path);

    my ($loaded_fh, $loaded_snapshot_path) =
        $workspace->tempfile('apparmor-loaded-profiles');
    close $loaded_fh || fatal('cannot create loaded profile snapshot');
    my ($names_fh, $profile_names_path) =
        $workspace->tempfile('apparmor-profile-names');
    close $names_fh || fatal('cannot create profile name snapshot');

    bounded_capture(
        'loaded AppArmor profile state',
        $options->{loaded_profiles_path},
        $loaded_snapshot_path,
        $limits->{max_loaded_profiles_bytes},
    );
    my $loaded_state = read_snapshot($loaded_snapshot_path);

    for my $entry (@$entries) {
        my $parse_path = $entry->{path};
        my $base_dir = $options->{profile_dir};
        my $label_work_dir;

        if ($entry->{mode} eq 'disable') {
            $label_work_dir = $workspace->tempdir('apparmor-profile-names');
            $parse_path = "$label_work_dir/$entry->{name}";
            $base_dir = $label_work_dir;
            $workspace->copy_file(
                $entry->{path},
                $parse_path,
                "cannot stage AppArmor profile for label derivation: $entry->{name}",
            );
        }

        $workspace->truncate_file($profile_names_path);
        $tools->run_stdout_to_file_or_exit(
            $profile_names_path,
            $parser_path,
            '-q',
            '-N',
            '-Q',
            '-K',
            '-T',
            '-I',
            $options->{profile_dir},
            '--base',
            $base_dir,
            $parse_path,
        );
        if (defined $label_work_dir) {
            $workspace->remove_dir($label_work_dir);
        }

        my $profile_names_size = file_size($profile_names_path);
        $profile_names_size > 0 ||
            fatal("AppArmor profile defines no labels: $entry->{name}");
        $profile_names_size <= $limits->{max_profile_names_bytes} ||
            fatal(
                'AppArmor profile labels exceed '
                . "$limits->{max_profile_names_bytes} bytes: $entry->{name}"
            );

        open my $labels_fh, '<:raw', $profile_names_path ||
            fatal("cannot derive AppArmor profile labels: $entry->{name}");
        while (my $profile_label = <$labels_fh>) {
            $profile_label =~ s/\n\z//;
            $profile_label ne '' ||
                fatal("AppArmor parser returned an empty label: $entry->{name}");
            length($profile_label) <= $limits->{max_line_bytes} ||
                fatal(
                    'AppArmor profile label exceeds '
                    . "$limits->{max_line_bytes} bytes: $entry->{name}"
                );

            if ($entry->{mode} eq 'disable') {
                !contains_label_prefix($loaded_state, $profile_label) ||
                    fatal("disabled AppArmor profile remains loaded: $profile_label");
            }
            elsif ($profile_label =~ m{//*}) {
                contains_exact_line(
                    $loaded_state,
                    "$profile_label (enforce)",
                ) || contains_exact_line(
                    $loaded_state,
                    "$profile_label (complain)",
                ) || fatal(
                    'AppArmor child profile is not loaded in a confined mode: '
                    . $profile_label
                );
            }
            else {
                contains_exact_line(
                    $loaded_state,
                    "$profile_label ($entry->{mode})",
                ) || fatal(
                    "AppArmor profile is not loaded in $entry->{mode} mode: "
                    . $profile_label
                );
            }
        }
        close $labels_fh ||
            fatal("cannot derive AppArmor profile labels: $entry->{name}");
    }

    info('loaded profile modes verified');
}

1;

package AppArmor::ManagedModes::Transition;

use strict;
use warnings;

use Exporter qw(import);

use AppArmor::ManagedModes::CLI qw(fatal info warn);

our @EXPORT_OK = qw(apply_profile_mode profile_mode_matches);

sub profile_mode_matches {
    my ($mode, $profile_name, $profile_path, $profile_dir) = @_;
    my $disable_link = "$profile_dir/disable/$profile_name";

    if ($mode eq 'complain') {
        return !-e $disable_link &&
            !-l $disable_link &&
            _file_has_match(
                $profile_path,
                qr/flags=\([^)]*complain(?:[[:space:],)]|\z)/,
            ) &&
            !_file_has_match(
                $profile_path,
                qr/flags=\([^)]*audit(?:[[:space:],)]|\z)/,
            );
    }
    if ($mode eq 'enforce') {
        return !-e $disable_link &&
            !-l $disable_link &&
            !_file_has_match(
                $profile_path,
                qr/flags=\([^)]*(?:audit|complain|default_allow|unconfined)/,
            );
    }
    if ($mode eq 'disable') {
        return -l $disable_link &&
            defined(readlink($disable_link)) &&
            readlink($disable_link) eq $profile_path;
    }
    return 0;
}

sub apply_profile_mode {
    my ($entry, $options, $workspace, $tools) = @_;
    my $mode = $entry->{mode};
    my $profile_name = $entry->{name};
    my $profile_path = $entry->{path};
    my $profile_dir = $options->{profile_dir};

    _validate_disable_entry($profile_name, $profile_path, $profile_dir);

    if ($mode eq 'enforce' || $mode eq 'complain') {
        if (profile_mode_matches($mode, $profile_name, $profile_path, $profile_dir)) {
            if (!$options->{reload_profiles}) {
                info("profile source already uses ${mode} mode: $profile_name");
                return;
            }
            info(
                "profile source already uses ${mode} mode; reloading: "
                . $profile_name
            );
        }

        my $disable_link = "$profile_dir/disable/$profile_name";
        unlink $disable_link if -l $disable_link;
    }

    if ($mode eq 'disable') {
        _disable_profile(
            $profile_name,
            $profile_path,
            $options,
            $workspace,
            $tools,
        );
        return;
    }
    $mode eq 'enforce' || $mode eq 'complain' ||
        fatal("unsupported AppArmor mode: $mode");

    my $tool_name = $mode eq 'enforce' ? 'aa-enforce' : 'aa-complain';
    my $tool_path = "$options->{tool_dir}/$tool_name";
    $tools->require_executable('required AppArmor tool', $tool_path);
    my $audit_tool_path = "$options->{tool_dir}/aa-audit";
    $tools->require_executable('required AppArmor audit tool', $audit_tool_path);

    my $mode_work_dir = $workspace->tempdir('apparmor-profile-mode');
    for my $include_name (qw(abi abstractions tunables local)) {
        my $include_path = "$options->{profile_dir}/$include_name";
        next if !-e $include_path;
        symlink $include_path, "$mode_work_dir/$include_name" ||
            fatal("cannot stage AppArmor profile include: $include_path");
    }

    my $mode_profile_path = "$mode_work_dir/$profile_name";
    $workspace->copy_file(
        $profile_path,
        $mode_profile_path,
        "cannot stage AppArmor profile for mode transition: $profile_name",
    );

    my $force_argument = $tools->force_argument($tool_name, $tool_path);
    my @mode_command = ($tool_path);
    push @mode_command, $force_argument if $force_argument ne '';
    push @mode_command, '--no-reload', '-d', $mode_work_dir, $mode_profile_path;
    $tools->run_or_exit(@mode_command);

    my @audit_command = ($audit_tool_path, '--remove');
    push @audit_command, '--no-reload' if !$options->{reload_profiles};
    push @audit_command, '-d', $mode_work_dir, $mode_profile_path;
    $tools->run_or_exit(@audit_command);

    profile_mode_matches(
        $mode,
        $profile_name,
        $mode_profile_path,
        $options->{profile_dir},
    ) || fatal("AppArmor profile did not enter ${mode} mode: $profile_name");

    my $publish_path = "$profile_path.managed.$$";
    $workspace->track_file($publish_path);
    $workspace->copy_file(
        $mode_profile_path,
        $publish_path,
        "cannot publish AppArmor profile mode: $profile_name",
    );
    rename $publish_path, $profile_path ||
        fatal("cannot publish AppArmor profile mode: $profile_name");
    $workspace->forget_file($publish_path);
    $workspace->remove_dir($mode_work_dir);
}

sub _disable_profile {
    my ($profile_name, $profile_path, $options, $workspace, $tools) = @_;
    my $profile_dir = $options->{profile_dir};
    my $disable_dir = "$profile_dir/disable";
    my $disable_link = "$disable_dir/$profile_name";

    _validate_disable_entry($profile_name, $profile_path, $profile_dir);
    if (!-d $disable_dir) {
        mkdir $disable_dir, 0755 ||
            fatal("cannot create AppArmor disable directory: $disable_dir");
    }
    if (!-l $disable_link) {
        symlink $profile_path, $disable_link ||
            fatal("cannot create AppArmor disable entry: $disable_link");
    }

    if ($options->{reload_profiles}) {
        my $parser_path = "$options->{tool_dir}/apparmor_parser";
        $tools->require_executable('required AppArmor parser', $parser_path);
        my ($error_fh, $error_snapshot) =
            $workspace->tempfile('apparmor-unload');
        close $error_fh || fatal('cannot create AppArmor unload error snapshot');

        my $status = $tools->run_with_stderr_file(
            $error_snapshot,
            $parser_path,
            '-I',
            $profile_dir,
            '--base',
            $profile_dir,
            '-R',
            $profile_path,
        );
        if ($status == 0) {
            # The parser removed the selected profile.
        }
        elsif (_file_contains($error_snapshot, q{Profile doesn't exist})) {
            info(
                'disabled AppArmor profile was already absent from the kernel: '
                . $profile_name
            );
        }
        else {
            _write_file_to_stderr($error_snapshot);
            warn(
                'could not unload disabled AppArmor profile; loaded-state '
                . "verification will decide: $profile_name"
            );
        }
        $workspace->remove_file($error_snapshot);
    }

    profile_mode_matches('disable', $profile_name, $profile_path, $profile_dir) ||
        fatal("AppArmor profile did not enter disable mode: $profile_name");
}

sub _validate_disable_entry {
    my ($profile_name, $profile_path, $profile_dir) = @_;
    my $disable_dir = "$profile_dir/disable";
    my $disable_link = "$disable_dir/$profile_name";

    if (-e $disable_dir || -l $disable_dir) {
        -d $disable_dir && !-l $disable_dir ||
            fatal("AppArmor disable path must be a real directory: $disable_dir");
    }
    if (-e $disable_link || -l $disable_link) {
        -l $disable_link &&
            defined(readlink($disable_link)) &&
            readlink($disable_link) eq $profile_path ||
            fatal(
                'AppArmor disable entry is not the managed symlink: '
                . $disable_link
            );
    }
}

sub _file_has_match {
    my ($path, $pattern) = @_;

    open my $fh, '<:raw', $path or return 0;
    while (my $line = <$fh>) {
        if ($line =~ $pattern) {
            close $fh;
            return 1;
        }
    }
    close $fh;
    return 0;
}

sub _file_contains {
    my ($path, $needle) = @_;

    open my $fh, '<:raw', $path or return 0;
    while (1) {
        my $buffer = '';
        my $read = sysread($fh, $buffer, 65_536);
        defined($read) || last;
        last if $read == 0;
        if (index($buffer, $needle) >= 0) {
            close $fh;
            return 1;
        }
    }
    close $fh;
    return 0;
}

sub _write_file_to_stderr {
    my ($path) = @_;

    open my $fh, '<:raw', $path or return;
    while (1) {
        my $buffer = '';
        my $read = sysread($fh, $buffer, 65_536);
        last if !defined($read) || $read == 0;
        print STDERR $buffer;
    }
    close $fh;
}

1;

package AppArmor::ManagedModes::LoadedState;

use strict;
use warnings;

use Exporter qw(import);

use AppArmor::ManagedModes::CLI qw(fatal);

our @EXPORT_OK = qw(
    contains_exact_line
    contains_label_prefix
    read_snapshot
);

sub read_snapshot {
    my ($path) = @_;

    open my $fh, '<:raw', $path ||
        fatal("cannot read loaded AppArmor profile state: $path");
    local $/;
    my $content = <$fh>;
    close $fh ||
        fatal("cannot read loaded AppArmor profile state: $path");
    return defined($content) ? $content : '';
}

sub contains_label_prefix {
    my ($snapshot, $label) = @_;
    return index($snapshot, "$label (") >= 0;
}

sub contains_exact_line {
    my ($snapshot, $line) = @_;

    for my $candidate (split(/\n/, $snapshot, -1)) {
        return 1 if $candidate eq $line;
    }
    return 0;
}

1;

package AppArmor::ManagedModes::Tool;

use strict;
use warnings;

use AppArmor::ManagedModes::CLI qw(fatal);
use POSIX qw(_exit);

sub new {
    return bless { force_arguments => {} }, shift;
}

sub require_executable {
    my ($self, $label, $path) = @_;
    -x $path || fatal("$label is missing: $path");
    return $path;
}

sub force_argument {
    my ($self, $tool_name, $tool_path) = @_;

    if (exists $self->{force_arguments}{$tool_name}) {
        return $self->{force_arguments}{$tool_name};
    }
    if ($tool_name ne 'aa-enforce' && $tool_name ne 'aa-complain') {
        fatal("unsupported AppArmor mode tool: $tool_name");
    }

    my $supports_force = $self->_output_contains(
        '--force',
        $tool_path,
        '--help',
    );
    $self->{force_arguments}{$tool_name} = $supports_force ? '--force' : '';
    return $self->{force_arguments}{$tool_name};
}

sub run_or_exit {
    my ($self, @command) = @_;
    my $status = system { $command[0] } @command;
    _exit_for_status($status) if $status != 0;
}

sub run_with_stderr_file {
    my ($self, $stderr_path, @command) = @_;

    open my $saved_stderr, '>&', \*STDERR ||
        fatal("cannot redirect AppArmor tool stderr: $stderr_path");
    open STDERR, '>:raw', $stderr_path ||
        fatal("cannot redirect AppArmor tool stderr: $stderr_path");
    my $status = system { $command[0] } @command;
    open STDERR, '>&', $saved_stderr ||
        fatal("cannot restore AppArmor tool stderr: $stderr_path");
    return $status;
}

sub run_stdout_to_file_or_exit {
    my ($self, $stdout_path, @command) = @_;

    open my $saved_stdout, '>&', \*STDOUT ||
        fatal("cannot redirect AppArmor tool output: $stdout_path");
    open STDOUT, '>:raw', $stdout_path ||
        fatal("cannot redirect AppArmor tool output: $stdout_path");
    my $status = system { $command[0] } @command;
    open STDOUT, '>&', $saved_stdout ||
        fatal("cannot restore AppArmor tool output: $stdout_path");
    _exit_for_status($status) if $status != 0;
}

sub _output_contains {
    my ($self, $needle, @command) = @_;
    pipe my $reader, my $writer ||
        fatal('cannot create AppArmor tool help pipe');
    my $pid = fork();
    defined($pid) || fatal('cannot fork AppArmor tool help probe');

    if ($pid == 0) {
        close $reader;
        open STDOUT, '>&', $writer || _exit(127);
        open STDERR, '>&', \*STDOUT || _exit(127);
        exec { $command[0] } @command;
        _exit(127);
    }

    close $writer;
    my $found = 0;
    my $tail = '';
    while (1) {
        my $buffer = '';
        my $read = sysread($reader, $buffer, 65_536);
        defined($read) || fatal('cannot read AppArmor tool help output');
        last if $read == 0;
        my $candidate = $tail . $buffer;
        $found = 1 if index($candidate, $needle) >= 0;
        my $tail_length = length($needle) - 1;
        $tail = $tail_length > 0 && length($candidate) > $tail_length
            ? substr($candidate, -$tail_length)
            : $candidate;
    }
    close $reader || fatal('cannot close AppArmor tool help pipe');
    waitpid($pid, 0);
    return $found;
}

sub _exit_for_status {
    my ($status) = @_;

    exit 1 if !defined($status) || $status == -1;
    my $signal = $status & 127;
    exit(128 + $signal) if $signal;
    exit($status >> 8);
}

1;

package AppArmor::ManagedModes::Workspace;

use strict;
use warnings;

use File::Copy qw(copy);
use File::Path qw(remove_tree);
use File::Temp qw(tempdir tempfile);

use AppArmor::ManagedModes::CLI qw(fatal);

sub new {
    my ($class) = @_;
    my $tmp_root = defined($ENV{TMPDIR}) && $ENV{TMPDIR} ne ''
        ? $ENV{TMPDIR}
        : '/tmp';

    return bless {
        directories => {},
        files       => {},
        tmp_root    => $tmp_root,
    }, $class;
}

sub tempfile {
    my ($self, $label) = @_;
    my ($fh, $path) = tempfile(
        "$label.XXXXXX",
        DIR    => $self->{tmp_root},
        UNLINK => 0,
    );
    binmode $fh, ':raw' ||
        fatal("cannot create $label snapshot");
    $self->{files}{$path} = 1;
    return ($fh, $path);
}

sub tempdir {
    my ($self, $label) = @_;
    my $path = tempdir(
        "$label.XXXXXX",
        DIR     => $self->{tmp_root},
        CLEANUP => 0,
    );
    $self->{directories}{$path} = 1;
    return $path;
}

sub copy_file {
    my ($self, $source, $target, $message) = @_;

    copy($source, $target) || fatal($message);
    chmod 0644, $target || fatal($message);
}

sub truncate_file {
    my ($self, $path) = @_;

    open my $fh, '>:raw', $path ||
        fatal("cannot create AppArmor profile name snapshot: $path");
    close $fh ||
        fatal("cannot create AppArmor profile name snapshot: $path");
}

sub track_file {
    my ($self, $path) = @_;
    $self->{files}{$path} = 1;
}

sub forget_file {
    my ($self, $path) = @_;
    delete $self->{files}{$path};
}

sub remove_file {
    my ($self, $path) = @_;
    unlink $path if -e $path || -l $path;
    delete $self->{files}{$path};
}

sub remove_dir {
    my ($self, $path) = @_;
    remove_tree($path, { safe => 1 }) if -d $path && !-l $path;
    delete $self->{directories}{$path};
}

sub cleanup {
    my ($self) = @_;

    for my $path (sort { length($b) <=> length($a) } keys %{$self->{directories}}) {
        remove_tree($path, { safe => 1 }) if -d $path && !-l $path;
    }
    for my $path (keys %{$self->{files}}) {
        unlink $path if -e $path || -l $path;
    }
    $self->{directories} = {};
    $self->{files} = {};
}

1;

