    26	validate_absolute_path('configuration path', $options->{config_path});
    27	validate_absolute_path('profile directory', $options->{profile_dir});
    28	validate_absolute_path('tool directory', $options->{tool_dir});
    29	validate_absolute_path('loaded profiles path', $options->{loaded_profiles_path});
    30	validate_real_directory('profile directory', $options->{profile_dir});
    31	
    32	umask 0077;
    33	
    34	my $workspace = AppArmor::ManagedModes::Workspace->new();
    35	END {
    36	    $workspace->cleanup() if defined $workspace;
    37	}
    38	
    39	my $entries = load_config($options);
    40	my $tools = AppArmor::ManagedModes::Tool->new();
    41	
    42	if ($options->{check_only}) {
    43	    verify_source_profile_modes($entries, $options->{profile_dir});
    44	}
    45	else {
    46	    for my $entry (@$entries) {
    47	        next if $entry->{mode} ne 'disable';
    48	        apply_profile_mode($entry, $options, $workspace, $tools);
    49	    }
    50	    for my $entry (@$entries) {
    51	        next if $entry->{mode} eq 'disable';
    52	        apply_profile_mode($entry, $options, $workspace, $tools);
    53	    }
    54	}
    55	
    56	if ($options->{check_loaded} ||
    57	    (!$options->{check_only} && $options->{reload_profiles})) {
    58	    verify_loaded_profile_modes($entries, $options, $workspace, $tools);
    59	}
    60	
    61	info('mode policy verified');
    62	exit 0;

