     1	package AppArmor::ManagedModes::CLI;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Exporter qw(import);
     7	
     8	our @EXPORT_OK = qw(fatal info parse_args usage warn);
     9	
    10	sub fatal {
    11	    my ($message) = @_;
    12	    print STDERR "fatal: $message\n";
    13	    exit 1;
    14	}
    15	
    16	sub info {
    17	    my ($message) = @_;
    18	    print "apparmor-managed-modes: $message\n";
    19	}
    20	
    21	sub warn {
    22	    my ($message) = @_;
    23	    print STDERR "apparmor-managed-modes: warning: $message\n";
    24	}
    25	
    26	sub usage {
    27	    print <<'USAGE';
    28	Usage: apparmor-managed-modes [--check] [--check-loaded] [--no-reload]
    29	                               [--config PATH] [--profile-dir PATH]
    30	                               [--tool-dir PATH] [--loaded-profiles PATH]
    31	USAGE
    32	}
    33	
    34	sub parse_args {
    35	    my @argv = @_;
    36	    my $options = {
    37	        config_path          => '/etc/apparmor/managed-modes.conf',
    38	        profile_dir          => '/etc/apparmor.d',
    39	        tool_dir             => '/usr/sbin',
    40	        reload_profiles      => 1,
    41	        check_only           => 0,
    42	        check_loaded         => 0,
    43	        loaded_profiles_path => '/sys/kernel/security/apparmor/profiles',
    44	    };
    45	
    46	    while (@argv) {
    47	        my $argument = shift @argv;
    48	
    49	        if ($argument eq '--check') {
    50	            $options->{check_only} = 1;
    51	        }
    52	        elsif ($argument eq '--check-loaded') {
    53	            $options->{check_only} = 1;
    54	            $options->{check_loaded} = 1;
    55	        }
    56	        elsif ($argument eq '--no-reload') {
    57	            $options->{reload_profiles} = 0;
    58	        }
    59	        elsif ($argument eq '--config') {
    60	            @argv or fatal('--config requires a path');
    61	            $options->{config_path} = shift @argv;
    62	        }
    63	        elsif ($argument eq '--profile-dir') {
    64	            @argv or fatal('--profile-dir requires a path');
    65	            $options->{profile_dir} = shift @argv;
    66	        }
    67	        elsif ($argument eq '--tool-dir') {
    68	            @argv or fatal('--tool-dir requires a path');
    69	            $options->{tool_dir} = shift @argv;
    70	        }
    71	        elsif ($argument eq '--loaded-profiles') {
    72	            @argv or fatal('--loaded-profiles requires a path');
    73	            $options->{loaded_profiles_path} = shift @argv;
    74	        }
    75	        elsif ($argument eq '-h' || $argument eq '--help') {
    76	            usage();
    77	            exit 0;
    78	        }
    79	        else {
    80	            fatal("unsupported argument: $argument");
    81	        }
    82	    }
    83	
    84	    return $options;
    85	}
