    87	1;

--- d-i/forky/hooks/shared/target/usr/local/libexec/apparmor-managed-modes/AppArmor/ManagedModes/Config.pm ---
     1	package AppArmor::ManagedModes::Config;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Exporter qw(import);
     7	
     8	use AppArmor::ManagedModes::CLI qw(fatal info warn);
     9	use AppArmor::ManagedModes::TrustedPath qw(
    10	    read_bounded_file
    11	    validate_absolute_path
    12	    validate_root_owned_file
    13	);
    14	
    15	our @EXPORT_OK = qw(limits load_config);
    16	
    17	sub limits {
    18	    return {
    19	        max_config_bytes          => 65_536,
    20	        max_profile_bytes         => 1_048_576,
    21	        max_line_bytes            => 1_024,
    22	        max_loaded_profiles_bytes => 8_388_608,
    23	        max_profile_names_bytes   => 65_536,
    24	    };
    25	}
    26	
    27	sub load_config {
    28	    my ($options) = @_;
    29	    my $limits = limits();
    30	
    31	    validate_root_owned_file(
    32	        'mode configuration',
    33	        $options->{config_path},
    34	        $limits->{max_config_bytes},
    35	    );
    36	
    37	    my $content = read_bounded_file(
    38	        'mode configuration',
    39	        $options->{config_path},
    40	        $limits->{max_config_bytes},
    41	    );
    42	    my @lines = length($content) ? split(/\n/, $content, -1) : ();
    43	    pop @lines if @lines && $content =~ /\n\z/;
    44	
    45	    my @entries;
    46	    my %seen_profiles;
    47	    my $line_number = 0;
    48	
    49	    for my $line (@lines) {
    50	        ++$line_number;
    51	        length($line) <= $limits->{max_line_bytes} ||
    52	            fatal(
    53	                "configuration line $line_number exceeds "
    54	                . "$limits->{max_line_bytes} bytes"
    55	            );
    56	        next if $line eq '' || $line =~ /\A#/;
    57	
    58	        $line =~ /\A[A-Za-z0-9._\/\@%:+,\-]+(?: +[A-Za-z0-9._\/\@%:+,\-]+){3}\z/ ||
    59	            fatal(
    60	                "configuration line $line_number contains unsupported "
    61	                . 'characters or spacing'
    62	            );
    63	
    64	        my @fields = split(/ +/, $line, -1);
    65	        @fields == 4 ||
    66	            fatal(
    67	                "configuration line $line_number must contain exactly four fields"
    68	            );
    69	
    70	        my ($mode, $presence, $profile_name, $executable_probe) = @fields;
    71	        $mode =~ /\A(?:enforce|complain|disable)\z/ ||
    72	            fatal(
    73	                "configuration line $line_number has an invalid mode: $mode"
    74	            );
    75	        $presence =~ /\A(?:required|optional|if-executable)\z/ ||
    76	            fatal(
    77	                "configuration line $line_number has an invalid presence policy: "
    78	                . $presence
    79	            );
    80	        $profile_name =~ /\A[A-Za-z0-9._+\-]+\z/ ||
    81	            fatal(
    82	                "configuration line $line_number has an invalid profile file: "
    83	                . $profile_name
    84	            );
    85	        !$seen_profiles{$profile_name}++ ||
    86	            fatal(
    87	                "configuration line $line_number repeats profile file: "
    88	                . $profile_name
    89	            );
    90	
    91	        if ($presence eq 'if-executable') {
    92	            validate_absolute_path(
    93	                'configuration executable probe',
    94	                $executable_probe,
    95	            );
    96	        }
    97	        else {
    98	            $executable_probe eq '-' ||
    99	                fatal(
   100	                    "configuration line $line_number must use '-' "
   101	                    . 'as its executable probe'
   102	                );
   103	        }
   104	
   105	        if ($presence eq 'if-executable' && !-x $executable_probe) {
   106	            info(
   107	                "skipping profile $profile_name; executable is absent: "
   108	                . $executable_probe
   109	            );
   110	            next;
   111	        }
   112	
   113	        my $profile_path = "$options->{profile_dir}/$profile_name";
   114	        if (!-e $profile_path) {
   115	            if ($presence eq 'required') {
   116	                fatal("required AppArmor profile is missing: $profile_name");
   117	            }
   118	            if ($presence eq 'if-executable') {
   119	                warn(
   120	                    'installed executable has no package AppArmor profile; '
   121	                    . "skipping mode management: $executable_probe -> "
   122	                    . $profile_name
   123	                );
   124	            }
   125	            else {
   126	                info("skipping absent optional profile $profile_name");
   127	            }
   128	            next;
   129	        }
   130	
   131	        validate_root_owned_file(
   132	            'AppArmor profile',
   133	            $profile_path,
   134	            $limits->{max_profile_bytes},
   135	        );
   136	        push @entries, {
   137	            mode => $mode,
   138	            name => $profile_name,
   139	            path => $profile_path,
   140	        };
   141	    }
   142	
   143	    return \@entries;
   144	}
   145	
   146	1;

