    17	    my ($path) = @_;
    18	
    19	    open my $fh, '<:raw', $path ||
    20	        fatal("cannot read loaded AppArmor profile state: $path");
    21	    local $/;
    22	    my $content = <$fh>;
    23	    close $fh ||
    24	        fatal("cannot read loaded AppArmor profile state: $path");
