    34	    my ($snapshot, $line) = @_;
    35	
    36	    for my $candidate (split(/\n/, $snapshot, -1)) {
    37	        return 1 if $candidate eq $line;
    38	    }
    39	    return 0;
    40	}
    41	
    42	1;

