     1	package AppArmor::ManagedModes::Tool;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use AppArmor::ManagedModes::CLI qw(fatal);
     7	use POSIX qw(_exit);
     8	
     9	sub new {
    10	    return bless { force_arguments => {} }, shift;
    11	}
    12	
    13	sub require_executable {
    14	    my ($self, $label, $path) = @_;
    15	    -x $path || fatal("$label is missing: $path");
    16	    return $path;
    17	}
    18	
    19	sub force_argument {
    20	    my ($self, $tool_name, $tool_path) = @_;
    21	
    22	    if (exists $self->{force_arguments}{$tool_name}) {
    23	        return $self->{force_arguments}{$tool_name};
    24	    }
    25	    if ($tool_name ne 'aa-enforce' && $tool_name ne 'aa-complain') {
    26	        fatal("unsupported AppArmor mode tool: $tool_name");
    27	    }
    28	
    29	    my $supports_force = $self->_output_contains(
    30	        '--force',
    31	        $tool_path,
    32	        '--help',
    33	    );
    34	    $self->{force_arguments}{$tool_name} = $supports_force ? '--force' : '';
    35	    return $self->{force_arguments}{$tool_name};
    36	}
    37	
    38	sub run_or_exit {
    39	    my ($self, @command) = @_;
    40	    my $status = system { $command[0] } @command;
    41	    _exit_for_status($status) if $status != 0;
    42	}
    43	
    44	sub run_with_stderr_file {
    45	    my ($self, $stderr_path, @command) = @_;
    46	
    47	    open my $saved_stderr, '>&', \*STDERR ||
    48	        fatal("cannot redirect AppArmor tool stderr: $stderr_path");
    49	    open STDERR, '>:raw', $stderr_path ||
    50	        fatal("cannot redirect AppArmor tool stderr: $stderr_path");
    51	    my $status = system { $command[0] } @command;
    52	    open STDERR, '>&', $saved_stderr ||
    53	        fatal("cannot restore AppArmor tool stderr: $stderr_path");
    54	    return $status;
    55	}
    56	
    57	sub run_stdout_to_file_or_exit {
    58	    my ($self, $stdout_path, @command) = @_;
    59	
    60	    open my $saved_stdout, '>&', \*STDOUT ||
    61	        fatal("cannot redirect AppArmor tool output: $stdout_path");
    62	    open STDOUT, '>:raw', $stdout_path ||
    63	        fatal("cannot redirect AppArmor tool output: $stdout_path");
    64	    my $status = system { $command[0] } @command;
    65	    open STDOUT, '>&', $saved_stdout ||
    66	        fatal("cannot restore AppArmor tool output: $stdout_path");
    67	    _exit_for_status($status) if $status != 0;
    68	}
    69	
    70	sub _output_contains {
    71	    my ($self, $needle, @command) = @_;
    72	    my ($reader, $writer);
    73	    pipe($reader, $writer) ||
    74	        fatal('cannot create AppArmor tool help pipe');
    75	    my $pid = fork();
    76	    defined($pid) || fatal('cannot fork AppArmor tool help probe');
    77	
    78	    if ($pid == 0) {
    79	        close $reader;
    80	        open STDOUT, '>&', $writer || _exit(127);
    81	        open STDERR, '>&', \*STDOUT || _exit(127);
    82	        exec { $command[0] } @command or _exit(127);
    83	    }
    84	
    85	    close $writer;
    86	    my $found = 0;
    87	    my $tail = '';
    88	    while (1) {
    89	        my $buffer = '';
    90	        my $read = sysread($reader, $buffer, 65_536);
    91	        defined($read) || fatal('cannot read AppArmor tool help output');
    92	        last if $read == 0;
    93	        my $candidate = $tail . $buffer;
    94	        $found = 1 if index($candidate, $needle) >= 0;
    95	        my $tail_length = length($needle) - 1;
    96	        $tail = $tail_length > 0 && length($candidate) > $tail_length
    97	            ? substr($candidate, -$tail_length)
    98	            : $candidate;
    99	    }
   100	    close $reader || fatal('cannot close AppArmor tool help pipe');
   101	    waitpid($pid, 0);
   102	    return $found;
   103	}
   104	
   105	sub _exit_for_status {
   106	    my ($status) = @_;
   107	
   108	    exit 1 if !defined($status) || $status == -1;
   109	    my $signal = $status & 127;
   110	    exit(128 + $signal) if $signal;
   111	    exit($status >> 8);
   112	}
   113	
   114	1;

--- d-i/forky/hooks/shared/target/usr/local/libexec/apparmor-managed-modes/AppArmor/ManagedModes/Transition.pm ---
     1	package AppArmor::ManagedModes::Transition;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Exporter qw(import);
     7	
     8	use AppArmor::ManagedModes::CLI qw(fatal info warn);
     9	
    10	our @EXPORT_OK = qw(apply_profile_mode profile_mode_matches);
    11	
    12	sub profile_mode_matches {
    13	    my ($mode, $profile_name, $profile_path, $profile_dir) = @_;
    14	    my $disable_link = "$profile_dir/disable/$profile_name";
    15	
    16	    if ($mode eq 'complain') {
    17	        return !-e $disable_link &&
    18	            !-l $disable_link &&
    19	            _file_has_match(
    20	                $profile_path,
    21	                qr/flags=\([^)]*complain(?:[[:space:],)]|\z)/,
    22	            ) &&
    23	            !_file_has_match(
    24	                $profile_path,
    25	                qr/flags=\([^)]*audit(?:[[:space:],)]|\z)/,
    26	            );
    27	    }
    28	    if ($mode eq 'enforce') {
    29	        return !-e $disable_link &&
    30	            !-l $disable_link &&
    31	            !_file_has_match(
    32	                $profile_path,
    33	                qr/flags=\([^)]*(?:audit|complain|default_allow|unconfined)/,
    34	            );
    35	    }
    36	    if ($mode eq 'disable') {
    37	        return -l $disable_link &&
    38	            defined(readlink($disable_link)) &&
    39	            readlink($disable_link) eq $profile_path;
    40	    }
    41	    return 0;
    42	}
    43	
    44	sub apply_profile_mode {
    45	    my ($entry, $options, $workspace, $tools) = @_;
    46	    my $mode = $entry->{mode};
    47	    my $profile_name = $entry->{name};
    48	    my $profile_path = $entry->{path};
    49	    my $profile_dir = $options->{profile_dir};
    50	
    51	    _validate_disable_entry($profile_name, $profile_path, $profile_dir);
    52	
    53	    if ($mode eq 'enforce' || $mode eq 'complain') {
    54	        if (profile_mode_matches($mode, $profile_name, $profile_path, $profile_dir)) {
    55	            if (!$options->{reload_profiles}) {
    56	                info("profile source already uses ${mode} mode: $profile_name");
    57	                return;
    58	            }
    59	            info(
    60	                "profile source already uses ${mode} mode; reloading: "
    61	                . $profile_name
    62	            );
    63	        }
    64	
    65	        my $disable_link = "$profile_dir/disable/$profile_name";
    66	        unlink $disable_link if -l $disable_link;
    67	    }
    68	
    69	    if ($mode eq 'disable') {
    70	        _disable_profile(
    71	            $profile_name,
    72	            $profile_path,
    73	            $options,
    74	            $workspace,
    75	            $tools,
    76	        );
    77	        return;
    78	    }
    79	    $mode eq 'enforce' || $mode eq 'complain' ||
    80	        fatal("unsupported AppArmor mode: $mode");
    81	
    82	    my $tool_name = $mode eq 'enforce' ? 'aa-enforce' : 'aa-complain';
    83	    my $tool_path = "$options->{tool_dir}/$tool_name";
    84	    $tools->require_executable('required AppArmor tool', $tool_path);
    85	    my $audit_tool_path = "$options->{tool_dir}/aa-audit";
    86	    $tools->require_executable('required AppArmor audit tool', $audit_tool_path);
    87	
    88	    my $mode_work_dir = $workspace->tempdir(
    89	        'apparmor-profile-mode',
    90	        'cannot create isolated AppArmor mode workspace',
    91	    );
    92	    for my $include_name (qw(abi abstractions tunables local)) {
    93	        my $include_path = "$options->{profile_dir}/$include_name";
    94	        next if !-e $include_path;
    95	        symlink $include_path, "$mode_work_dir/$include_name" ||
    96	            fatal("cannot stage AppArmor profile include: $include_path");
    97	    }
    98	
    99	    my $mode_profile_path = "$mode_work_dir/$profile_name";
   100	    $workspace->copy_file(
   101	        $profile_path,
   102	        $mode_profile_path,
   103	        "cannot stage AppArmor profile for mode transition: $profile_name",
   104	    );
   105	
   106	    my $force_argument = $tools->force_argument($tool_name, $tool_path);
   107	    my @mode_command = ($tool_path);
   108	    push @mode_command, $force_argument if $force_argument ne '';
   109	    push @mode_command, '--no-reload', '-d', $mode_work_dir, $mode_profile_path;
   110	    $tools->run_or_exit(@mode_command);
   111	
   112	    my @audit_command = ($audit_tool_path, '--remove');
   113	    push @audit_command, '--no-reload' if !$options->{reload_profiles};
   114	    push @audit_command, '-d', $mode_work_dir, $mode_profile_path;
   115	    $tools->run_or_exit(@audit_command);
   116	
   117	    profile_mode_matches(
   118	        $mode,
   119	        $profile_name,
   120	        $mode_profile_path,
   121	        $options->{profile_dir},
   122	    ) || fatal("AppArmor profile did not enter ${mode} mode: $profile_name");
   123	
   124	    my $publish_path = "$profile_path.managed.$$";
   125	    $workspace->track_file($publish_path);
   126	    $workspace->copy_file(
   127	        $mode_profile_path,
   128	        $publish_path,
   129	        "cannot publish AppArmor profile mode: $profile_name",
   130	    );
   131	    rename $publish_path, $profile_path ||
   132	        fatal("cannot publish AppArmor profile mode: $profile_name");
   133	    $workspace->forget_file($publish_path);
   134	    $workspace->remove_dir($mode_work_dir);
   135	}
   136	
   137	sub _disable_profile {
   138	    my ($profile_name, $profile_path, $options, $workspace, $tools) = @_;
   139	    my $profile_dir = $options->{profile_dir};
   140	    my $disable_dir = "$profile_dir/disable";
   141	    my $disable_link = "$disable_dir/$profile_name";
   142	
   143	    _validate_disable_entry($profile_name, $profile_path, $profile_dir);
   144	    if (!-d $disable_dir) {
   145	        mkdir $disable_dir, 0755 ||
   146	            fatal("cannot create AppArmor disable directory: $disable_dir");
   147	    }
   148	    if (!-l $disable_link) {
   149	        symlink $profile_path, $disable_link ||
   150	            fatal("cannot create AppArmor disable entry: $disable_link");
   151	    }
   152	
   153	    if ($options->{reload_profiles}) {
   154	        my $parser_path = "$options->{tool_dir}/apparmor_parser";
   155	        $tools->require_executable('required AppArmor parser', $parser_path);
   156	        my ($error_fh, $error_snapshot) =
   157	            $workspace->tempfile(
   158	                'apparmor-unload',
   159	                'cannot create AppArmor unload error snapshot',
   160	            );
   161	        close $error_fh || fatal('cannot create AppArmor unload error snapshot');
   162	
   163	        my $status = $tools->run_with_stderr_file(
   164	            $error_snapshot,
