    60	    my $content = '';
    61	    my $remaining = $max_bytes + 1;
    62	    while ($remaining > 0) {
    63	        my $buffer = '';
    64	        my $read = sysread(
    65	            $fh,
    66	            $buffer,
    67	            $remaining > 65_536 ? 65_536 : $remaining,
    68	        );
